type Message =
  | { kind: "created"; id: string }
  | { kind: "deleted"; id: string };

function assertNever(x: never): never { throw new Error(`unhandled ${JSON.stringify(x)}`); }

export function dispatch(msg: Message): Promise<void> {
  switch (msg.kind) {
    case "created": return onCreate(msg);
    case "deleted": return onDelete(msg);
    default: return assertNever(msg);   // new message kinds fail to compile
  }
}
